from ..config import loggers as ute_ue_logging
from ..config import abstract_core_logger_wrapper as core_logger


class AliasExtendedFormatter(core_logger.ExtendedFormatter):
    """Alias is for end-user (tester) to show alias used inside tests"""
    def __init__(self):
        """Initialize base class with format string containing %(alias)"""
        super().__init__(fmt="%(asctime)s %(levelname)-10s  %(alias)-14s |%(message)s")

    def format(self, record):
        """Ensure log record has .alias to allow for "%(alias)" in format string"""
        if not hasattr(record, "alias"):
            record.alias = " "
        return super().format(record)


class UeInfoAndAliasExtendedFormatter(core_logger.ExtendedFormatter):
    """Library developer needs also library-AREA to help in troubleshooting"""
    def __init__(self):
        """Initialize base class with format string containing %(area)s %(alias)s %(ue_id)s"""
        log_fmt = "%(asctime)s | %(levelname)-8s | %(area)-15s %(alias)-10s %(ue_id)-10s | " \
                  "%(message)s /// %(threadName)-11s: %(filename)s(%(lineno)d)"
        super().__init__(fmt=log_fmt)

    def format(self, record):
        """Ensure log record has .area .ueid .alias to allow for "%(area)s %(alias)s %(ue_id)s" in format string"""
        if not hasattr(record, "alias"):
            record.alias = " "
        if not hasattr(record, "area"):
            record.area = " "
        if not hasattr(record, "ue_id"):
            record.ue_id = ""
        elif record.ue_id and (not record.ue_id.startswith("UE")):
            record.ue_id = f"UE:{record.ue_id}"
        line = super().format(record)
        return line


def configure_loggers():
    """Configure all loggers for robot layer."""
    ute_ue_logging.configure_loggers(formatter=AliasExtendedFormatter(),
                                     debug_formatter=UeInfoAndAliasExtendedFormatter())
